import sympy

def build_instance(rng):
    constant = rng.randint(-10, 10)
    x = sympy.symbols('x', real=True)
    f = x ** 3 - 3 * x ** 2 + 2 * x - constant
    roots = sympy.solve(f, x)
    answer = len([root for root in roots if root.is_real])
    check = sum((1 for root in roots if root.is_real))
    assert answer == check, f'answer={answer} check={check}'
    parameters = {'constant': constant}
    return (parameters, answer, check)



