import itertools

def build_instance(rng):
    rows = rng.randint(2, 10)
    columns = rng.randint(2, 10)
    right_moves = rng.randint(1, rows - 1)
    down_moves = rng.randint(1, columns - 1)
    total_moves = right_moves + down_moves
    answer = math.comb(total_moves, right_moves)
    check = sum((1 for _ in itertools.combinations(range(total_moves), right_moves)))
